const deliveredStatus=messages=>{const user=[...messages].reverse().find(item=>item.role==='user'&&item.content.includes('Current Gmail status at this provider dispatch: '));assert.ok(user,'Missing current Gmail dispatch status');const json=user.content.split('Current Gmail status at this provider dispatch: ').at(-1).split('\n')[0];return JSON.parse(json).gmailConnectionAtDelivery.status;};
