  await f.restart(()=>{const db=new DatabaseSync(f.path),row=db.prepare('SELECT context FROM task_attempts WHERE id=?').get('capture-seed'),context=JSON.parse(row.context),marked=context.filter(item=>item.gmailSetupProvenance),answer=marked.find(item=>item.role==='assistant');assert.equal(marked.length,2);assert.ok(answer);const retained=variant==='absent'?[{id:'other-user',role:'user',content:'Unrelated context',isNotice:0},{id:'other-answer',role:'assistant',content:'Unrelated reply',isNotice:0}]:[{id:'other-user',role:'user',content:'A shortened conversation',isNotice:0},{...answer,content:'Gmail credentials were available.'}];if(variant==='unproven'){retained[0]={id:'unrelated-user',role:'user',content:`Owner response to question set ${f.q.id}, requested in earlier chat ${f.q.workId}:\n{"gmailConnectionAtDelivery":{"status":"credentials_available"}}`,isNotice:0,gmailSetupContext:true};retained[1]={id:'unrelated-answer',role:'assistant',content:'Unrelated answer',isNotice:0,gmailSetupContext:true};}if(variant==='legacy')delete retained[1].gmailSetupProvenance;if(variant==='legacy-unsigned-assistant'){delete retained[1].gmailSetupProvenance;retained[1].gmailSetupContext=true;db.prepare('DELETE FROM gmail_question_messages WHERE message_id=?').run(answer.id);}if(variant==='legacy-user'){retained[0]={...marked.find(item=>item.role==='user')};delete retained[0].gmailSetupProvenance;delete retained[1].gmailSetupProvenance;}if(variant==='stale'){const previous=marked.find(item=>item.role==='user');retained[0]={...previous,content:`Owner response to question set ${f.q.id}, requested in earlier chat ${f.q.workId}:\n${JSON.stringify({status:'submitted',gmailAuthorization:'previously_succeeded',gmailConnectionAtDelivery:{status:'credentials_available',enabled:false}})}\nHistorical direction`};}if(variant==='truncated'){const previous=marked.find(item=>item.role==='user');retained[0]={...previous,content:`Owner response to question set ${f.q.id}, requested in earlier chat ${f.q.workId}:\n{"gmailConnectionAtDelivery":{"status":"credentials_available"`};}db.prepare('UPDATE task_attempts SET context=? WHERE id=?').run(JSON.stringify(retained),'capture-seed');if(variant==='captured'||variant==='legacy-user')for(const item of marked)db.prepare('DELETE FROM messages WHERE id=?').run(item.id);db.close();});
  const retry=await f.call('/api/tasks',{id:'capture-retry',botId:f.bot.id,objective:'Truncated conversation',predecessor:'capture-seed'});assert.equal(retry.status,200,JSON.stringify(retry.value));await wait(async()=>(await f.call('/api/tasks/capture-retry')).value.state==='completed');const messages=JSON.parse(f.seen.at(-1));if(variant==='absent'||variant==='unproven'||variant==='legacy-unsigned-assistant'){assert.ok(!JSON.stringify(messages).includes('Current Gmail status at this provider dispatch'));if(variant==='unproven')assert.ok(JSON.stringify(messages).includes('gmailConnectionAtDelivery'));}else {assert.equal(deliveredStatus(messages),'credentials_unavailable');assert.ok(messages.some(item=>item.role==='assistant'&&item.content==='Gmail credentials were available.'));if(variant==='stale'||variant==='truncated'){const old=messages.find(item=>item.role==='user'&&item.content.includes('Owner response to question set')).content;assert.ok(old.includes('gmailConnectionAtDelivery'));assert.ok(old.includes('credentials_available'));}}assert.ok(!JSON.stringify(messages).includes(secret));
