  const route=`/api/question-sets/${f.q.id}`,preview=(await f.call(route+'/gmail-preview')).value,start=await f.call(route+'/gmail-start',{...preview,confirm:true,confirmDisplacements:false});assert.equal((await fetch(callback(start.value.url))).status,200);await f.call(route+'/submit',{});await wait(async()=>(await f.call('/api/question-sets')).value.find(q=>q.id===f.q.id).continuationState==='completed');assert.ok(f.seen.at(-1).includes(preserved));
  assert.equal((await f.call('/api/secrets/add',{name:'New confidential value',purpose:'Fixture',value:marker})).status,200);
  await f.call('/api/commands',{id:'unrelated-check-1',botId:f.bot.id,content:'First follow-up'});await wait(async()=>(await f.call('/api/commands/unrelated-check-1')).value.state==='completed');assert.ok(f.seen.at(-1).includes(preserved));
  await f.restart(()=>{const db=new DatabaseSync(f.path,{readOnly:true}),session=JSON.parse(db.prepare('SELECT session FROM sessions WHERE bot_id=?').get(f.bot.id).session),turn=session.turns.find(item=>item.gmailSetup),text=session.messages[turn.start].content;assert.ok(turn.gmailSetup.result);assert.ok(text.slice(0,turn.gmailSetup.result.start).includes(preserved));assert.ok(!text.slice(turn.gmailSetup.result.start,turn.gmailSetup.result.end).includes(preserved));db.close();});
